设计首页布局&lt;body class=&quot;container&quot;&gt;    &lt;div class=&quot;row&quot;&gt;        &lt;!--左侧导航--&gt;        &lt;div class=&quot;col-12 col-lg-3 left&quot;&gt;            &lt;!--导航条--&gt;            &lt;ul class=&quot;nav&quot;&gt;&lt;/ul&gt;            &lt;!--隐藏导航栏--&gt;            &lt;div id=&quot;template2&quot; class=&quot;d-none&quot;&gt;&lt;/div&gt;        &lt;/div&gt;        &lt;!--右侧主体内容--&gt;        &lt;div class=&quot;col-12 col-lg-9 right p-0 clearfix&quot;&gt;            &lt;!--轮播广告区--&gt;            &lt;div id=&quot;carouselExampleControls&quot; class=&quot;carousel slide&quot; data-ride=&quot;carousel&quot;&gt;&lt;/div&gt;            &lt;!--产品推荐区--&gt;            &lt;div class=&quot;p-4 list&quot;&gt;&lt;/div&gt;            &lt;!--登陆注册区和logo--&gt;            &lt;div class=&quot;row py-5&quot;&gt;&lt;/div&gt;            &lt;!--特色展示区--&gt;            &lt;div class=&quot;p-4 list&quot;&gt;&lt;/div&gt;            &lt;!--产品生产流程区--&gt;            &lt;div class=&quot;p-4&quot;&gt;&lt;/div&gt;        &lt;/div&gt;    &lt;/div&gt;    &lt;!--隐藏导航栏--&gt;    &lt;div class=&quot;row fixed-bottom d-block d-sm-none bg-light border-top py-1&quot; id=&quot;footer&quot;&gt;&lt;/div&gt;&lt;/body&gt;

