工作经历&lt;!--工作经历--&gt;&lt;h5 class=&quot;color1&quot;&gt;工作经历&lt;/h5&gt;&lt;div class=&quot;px-5 py-2&quot;&gt;    &lt;table class=&quot;table&quot;&gt;        &lt;thead class=&quot;table-success&quot;&gt;        &lt;tr&gt;            &lt;th scope=&quot;col&quot;&gt;#&lt;/th&gt;            &lt;th scope=&quot;col&quot;&gt;时间&lt;/th&gt;            &lt;th scope=&quot;col&quot;&gt;单位&lt;/th&gt;            &lt;th scope=&quot;col&quot;&gt;职位&lt;/th&gt;        &lt;/tr&gt;        &lt;/thead&gt;        &lt;tbody class=&quot;table-info&quot;&gt;        &lt;tr&gt;            &lt;th&gt;1&lt;/th&gt;            &lt;td&gt;2018/8-2019/10&lt;/td&gt;            &lt;td&gt;八面恒通网络公司&lt;/td&gt;            &lt;td&gt;软件测试工程师&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;            &lt;th&gt;2&lt;/th&gt;            &lt;td&gt;2019/11-2020/10&lt;/td&gt;            &lt;td&gt;千古网络科技公司&lt;/td&gt;            &lt;td&gt;软件工程师&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;            &lt;th&gt;3&lt;/th&gt;            &lt;td&gt;2020/12-至今&lt;/td&gt;            &lt;td&gt;冰原网络科技公司&lt;/td&gt;            &lt;td&gt;前端工程师&lt;/td&gt;        &lt;/tr&gt;        &lt;/tbody&gt;    &lt;/table&gt;&lt;/div&gt;

专业技能&lt;!--专业技能--&gt;&lt;h5 class=&quot;color2&quot;&gt;专业技能&lt;/h5&gt;&lt;div class=&quot;px-5 py-2&quot;&gt;    &lt;!--嵌套格栅--&gt;    &lt;div class=&quot;row&quot;&gt;        &lt;div class=&quot;col-6&quot;&gt;            &lt;!--使用卡片组件--&gt;            &lt;div class=&quot;card border-primary text-primary&quot;&gt;                &lt;div class=&quot;card-header border-primary&quot;&gt;擅长的技能&lt;/div&gt;                &lt;div class=&quot;card-body&quot;&gt;                    &lt;p class=&quot;card-text&quot;&gt;                        HTML、CSS、JavaScript、jQuery、bootstrap、Vue.js、Angular.js、node.js、PHP、MySQL&lt;/p&gt;                &lt;/div&gt;            &lt;/div&gt;        &lt;/div&gt;        &lt;div class=&quot;col-6&quot;&gt;            &lt;div class=&quot;card border-success text-success&quot;&gt;                &lt;div class=&quot;card-header border-success&quot;&gt;熟悉的技能&lt;/div&gt;                &lt;div class=&quot;card-body&quot;&gt;                    &lt;p class=&quot;card-text&quot;&gt;C语言、C++、C#、Java、Oracle、Python&lt;/p&gt;                &lt;/div&gt;            &lt;/div&gt;        &lt;/div&gt;    &lt;/div&gt;&lt;/div&gt;

